import"./modulepreload-polyfill-B5Qt9EMX.js";import{m as c}from"./foundation-module-BgS6mBLm.js";const p='<div class="fm-object-stage" role="img" aria-label="A cube with width, height, and depth labeled"><div class="fm-cube"></div><span class="fm-dim width">width</span><span class="fm-dim height">height</span><span class="fm-dim depth">depth</span></div>',n='<div class="fm-object-stage fm-organizer-stage" role="img" aria-label="A desk organizer made from three box shapes"><div class="fm-organizer base"></div><div class="fm-organizer cup"></div><div class="fm-organizer tray"></div></div>',r=(t,o,a,i,s,h=20)=>({id:t,short:o,title:a,summary:i,minutes:h,kind:"choice",items:s}),e=(t,o,a,i,s,h,l,d="")=>({title:t,question:o,options:a,answer:i,skill:s,feedback:h,retry:l,visual:d}),m={id:"MOD-3D-MODELLING-01",slug:"3d-modelling-foundations",version:"0.1.0",storageKey:"mod-3d-modelling-01-v0.1.0",mark:"3D",shortTitle:"3D modelling",title:"3D Modelling Foundations",sections:[{id:"start",short:"Start",title:"Build an idea in 3D",summary:"Learn the moves you need before making a three-shape desk organizer in Tinkercad.",minutes:5,html:`<section class="fm-opening"><div><p class="fm-label">Goal</p><h2>From simple shapes to one useful model</h2><p>A 3D model has width, height, and depth. You will inspect shapes, practice modelling decisions, plan an organizer, and then build it in Tinkercad.</p></div>${n}</section><section class="fm-note"><strong>This module is your practice space.</strong> Your real model is made in Tinkercad. No formal grade is stored here.</section>`},{id:"space",short:"3D space",title:"Understand 3D space",summary:"See how width, height, and depth describe a solid object.",minutes:10,html:`<section class="fm-block"><p class="fm-label">Look</p><h2>A flat shape becomes a solid object when it has depth</h2>${p}<div class="fm-concept-grid"><div><h3>Width</h3><p>Side to side.</p></div><div><h3>Height</h3><p>Bottom to top.</p></div><div><h3>Depth</h3><p>Front to back.</p></div></div><p class="fm-note">A model can look different when you turn your view. Its measurements do not change.</p></section>`},r("views","View practice","Practice reading 3D views","Use front, side, top, and perspective views to understand an object.",[e("Find the top view","Which view best shows the length and width of a tray?",["Top","Front","Side"],0,"Choose a useful view","The top view shows the tray opening and its length and width.","Imagine looking straight down at the tray."),e("Find the front view","Which view best shows the height of a pencil holder?",["Top","Front","Bottom"],1,"Choose a useful view","The front view makes the holder's height easy to compare.","Look for the view that shows bottom to top."),e("Use perspective","Which view helps you see width, height, and depth together?",["Perspective","Top","Front"],0,"Recognize perspective","Perspective shows several sides of the object at once.","Choose the view that looks most like a solid object."),e("Check hidden space","The tray looks correct from the front. What should you do next?",["Check the top and side views","Add more shapes immediately","Change every measurement"],0,"Check more than one view","Different views can reveal overlaps or gaps.","One view cannot show every side of a 3D model."),e("Keep measurements","You rotate the view around a 30 mm cube. What changes?",["Only what you can see","Its measurements","Its shape"],0,"Separate view from object","Rotating the view does not change the cube.","You are moving your viewpoint, not editing the cube.")]),{id:"transform-learn",short:"Learn moves",title:"Move, resize, rotate, and duplicate",summary:"Learn what each basic modelling tool changes.",minutes:12,html:'<section class="fm-block"><p class="fm-label">Learn</p><h2>Choose the tool that matches the change</h2><div class="fm-model-actions"><div><h3>Move</h3><p>Change position.</p></div><div><h3>Resize</h3><p>Change measurements.</p></div><div><h3>Rotate</h3><p>Change direction.</p></div><div><h3>Duplicate</h3><p>Make an exact copy.</p></div></div><ol class="fm-steps"><li><p><strong>Select</strong> the shape you want to change.</p></li><li><p>Use <strong>one tool</strong> and check what changed.</p></li><li><p>Check the model from more than one view.</p></li></ol></section>'},r("transform-practice","Move practice","Practice choosing modelling tools","Decide which tool completes each change.",[e("Position a tray","The tray is too far from the pencil holder. Which tool should you use?",["Move","Resize","Duplicate"],0,"Choose Move","Move changes where the tray sits.","The size is correct; only the position is wrong."),e("Make a taller holder","The pencil holder is too short. Which tool should you use?",["Rotate","Resize","Group"],1,"Choose Resize","Resize changes the holder's height.","You need to change a measurement."),e("Turn a divider","A divider points in the wrong direction. Which tool should you use?",["Duplicate","Rotate","Move"],1,"Choose Rotate","Rotate changes the direction the divider faces.","The shape needs to turn."),e("Make equal compartments","You need a second divider exactly like the first. Which tool is fastest?",["Duplicate","Resize","Delete"],0,"Choose Duplicate","Duplicate makes an exact copy.","You already have the correct shape."),e("Fix one shape","Two shapes are selected, but only the tray should move. What should you do first?",["Select only the tray","Resize both shapes","Delete the holder"],0,"Select before editing","Selecting the correct object prevents unwanted changes.","Control which shape the tool will affect.")]),{id:"combine-learn",short:"Learn combining",title:"Combine simple shapes",summary:"Place three boxes so they work as one desk organizer.",minutes:12,html:`<section class="fm-block"><p class="fm-label">Look</p><h2>One model can be made from several shapes</h2>${n}<div class="fm-concept-grid"><div><h3>Base</h3><p>Keeps every part connected.</p></div><div><h3>Holder</h3><p>Tall space for pencils.</p></div><div><h3>Tray</h3><p>Low space for small items.</p></div></div><p class="fm-note"><strong>Group</strong> only after the parts are placed and checked. Group makes selected shapes act like one object.</p></section>`},r("combine-practice","Combine practice","Practice building in a sensible order","Choose the next useful action for each model.",[e("Start with a base","What should you create first for the three-shape organizer?",["A stable base","A random decoration","A second project"],0,"Start with structure","The base gives the other shapes a clear place to sit.","Think about what supports the whole model."),e("Connect the holder","The pencil holder floats above the base. What should you do?",["Move it down to touch the base","Make it brighter","Duplicate the base"],0,"Connect parts","Connected parts make the model buildable as one object.","Check the position, not the color."),e("Protect the tray","The tray is completely inside the holder. What is the problem?",["The tray space cannot be used","The model has depth","The base is stable"],0,"Notice overlap","Too much overlap can hide or block a useful part.","Ask whether a user can reach the tray."),e("Group at the right time","When should you group the three shapes?",["After their size and position are checked","Before adding any shapes","Every time you rotate the view"],0,"Group deliberately","Check first, then group the finished arrangement.","Grouping too early can make corrections harder."),e("Test usefulness","Which check tells you whether the model solves its purpose?",["Pencils fit and the tray remains reachable","Every shape has a different color","The model fills the whole workplane"],0,"Test the design goal","A useful organizer must hold the intended items.","Judge the function, not decoration.")]),{id:"plan",short:"Plan model",title:"Plan your desk organizer",summary:"Decide the purpose and measurements before opening Tinkercad.",minutes:15,kind:"form",prompt:"Record a buildable plan",intro:'<section class="fm-note"><strong>Required model:</strong> one base, one pencil holder, and one tray. Use millimetres for every measurement.</section>',fields:[{name:"purpose",label:"What will the organizer hold?",type:"textarea",rows:2,help:"Name the objects and how the organizer will help."},{name:"base",label:"Base: width × depth × height (mm)",help:"Example format: 100 × 70 × 5"},{name:"holder",label:"Pencil holder: width × depth × height (mm)",help:"Make it tall enough to hold pencils."},{name:"tray",label:"Tray: width × depth × height (mm)",help:"Make it low enough to reach small items."},{name:"check",label:"How will you test that the organizer works?",type:"textarea",rows:3,help:"Describe one clear fit or stability test."}]},{id:"handoff",short:"Build in Tinkercad",title:"Build and check in Tinkercad",summary:"Follow your plan, save clearly, and record what changed.",minutes:25,kind:"form",prompt:"Record your Tinkercad work",intro:'<section class="fm-block"><p class="fm-label">Build</p><h2>Use this order</h2><ol class="fm-steps"><li><p>Create the base, holder, and tray.</p></li><li><p>Enter the planned measurements.</p></li><li><p>Move the parts so they touch correctly.</p></li><li><p>Check top, front, side, and perspective views.</p></li><li><p>Group the finished shapes and use a clear file name.</p></li></ol></section>',fields:[{name:"filename",label:"Tinkercad file name",help:"Use class, name, and organizer, for example 6A-Maria-Organizer."},{name:"change",label:"What did you change from your plan, and why?",type:"textarea",rows:3},{name:"test",label:"What happened when you checked fit and stability?",type:"textarea",rows:3}]},{id:"history",short:"History & export",title:"Review and export your practice",summary:"Recreate saved attempts and download one practice report.",minutes:10,kind:"review"}]};c(m);
